import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import TSL from 'three/tsl';

const { texture, uv, mix, sin, fract, vec3, float } = TSL;

export default function createNode(config, ctx) {
  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load image texture from assets
  const imageTexture = ctx.textureLoader.load(config.assets.imageUrl);
  imageTexture.colorSpace = THREE.SRGBColorSpace;

  // Create material using TSL nodes
  const material = new MeshBasicNodeMaterial();

  // Get UV coordinates
  const uvCoord = uv();

  // Sample base texture
  const texColor = texture(imageTexture, uvCoord);

  // Generate subtle grain pattern using procedural noise
  const noiseVal = sin(
    uvCoord.x.mul(12.9898).add(uvCoord.y.mul(78.233))
  ).mul(43758.5453);
  const grainPattern = fract(noiseVal);

  // Blend texture with 2% grain effect for engineered surface
  const finalColor = mix(texColor, vec3(grainPattern), float(0.02));

  // Assign final color to material
  material.colorNode = finalColor;

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement from config or defaults from spec
  const pos = config.scenePosition || [0, -0.3, 0];
  const rot = config.sceneRotation || [0, 0, 0];
  const scale = config.sceneScale || [1, 1, 1];

  mesh.position.fromArray(pos);
  mesh.rotation.order = 'XYZ';
  mesh.rotation.fromArray(rot);
  mesh.scale.fromArray(scale);

  // Setup cleanup handler
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
  };

  return mesh;
}
